/*
 * CSHealthED Basic ECG Interpretation: the Live Monitor.
 *
 * The same cardiac monitor as the Cardiac Lab defib trainer (device, screen,
 * sweeping ECG, SpO2 pleth, CO2 and the numeric boxes), playing strips from the
 * Live Monitor bank (js/monitor-strips.js). Each strip is generated by the
 * course's ECG engine from its rhythm and seed, and looped seamlessly at a beat.
 *
 * window.ECGLiveMonitor(host, { onPrint(info) }) → { load(strip), destroy() }
 */
(function (global) {
  'use strict';

  var SWEEP = 4.6;                      // seconds across the ECG trace, as on the defib trainer
  var PULSELESS = { vf: 1, asystole: 1, torsades: 1 };
  var LEADS = ['I', 'II', 'III'];
  var BANK = global.ECGMonitorBank;

  /* ---------- sound: Web Audio QRS beep, as on the defib trainer ---------- */
  var AU = { ctx: null, master: null, on: true };
  try { AU.on = localStorage.getItem('cshealthed-monitor-sound') !== '0'; } catch (e) { /* storage blocked */ }
  function audio() {
    if (!AU.on) return null;
    if (!AU.ctx) {
      try { AU.ctx = new (global.AudioContext || global.webkitAudioContext)(); AU.master = AU.ctx.createGain(); AU.master.gain.value = 0.16; AU.master.connect(AU.ctx.destination); }
      catch (e) { AU.ctx = null; return null; }
    }
    if (AU.ctx.state === 'suspended') { try { AU.ctx.resume(); } catch (e) { /* ignore */ } }
    return AU.ctx;
  }
  function tone(freq, delay, dur, type, vol) {
    var c = audio(); if (!c) return;
    var o = c.createOscillator(), g = c.createGain(), t0 = c.currentTime + Math.max(0, delay || 0), v = vol == null ? 1 : vol;
    o.type = type || 'sine'; o.frequency.setValueAtTime(freq, t0);
    g.gain.setValueAtTime(0.0001, t0); g.gain.linearRampToValueAtTime(v, t0 + 0.01);
    g.gain.setValueAtTime(v, t0 + Math.max(0.011, dur - 0.03)); g.gain.linearRampToValueAtTime(0.0001, t0 + dur);
    o.connect(g); g.connect(AU.master); o.start(t0); o.stop(t0 + dur + 0.05);
  }

  function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
  function sampleAt(sig, lead, t) {
    var s = sig.leads[lead], x = t * sig.fs;
    if (x < 0 || x >= s.length - 1) return 0;
    var i = Math.floor(x), f = x - i;
    return s[i] * (1 - f) + s[i + 1] * f;
  }

  function deviceHTML() {
    return '' +
      '<div class="dv" id="dv">' +
      '  <div class="dv-handle" aria-hidden="true"></div>' +
      '  <div class="dv-face">' +
      '    <div class="dv-brand"><span class="dv-logo"></span><b>CSHealthED</b><span>Cardiac monitor · rhythm trainer</span><button class="dv-snd' + (AU.on ? '' : ' off') + '" data-k="sound" aria-pressed="' + AU.on + '" title="Monitor sound on or off"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 9v6h4l5 4V5L8 9z" fill="currentColor"/><path class="w" d="M16 8.5a5 5 0 0 1 0 7M18.5 6a8.5 8.5 0 0 1 0 12" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/><path class="x" d="M16 9l5 6M21 9l-5 6" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg><span>' + (AU.on ? 'SOUND ON' : 'SOUND OFF') + '</span></button><i class="dv-pwr" title="Power">●</i></div>' +
      '    <div class="dv-main">' +
      '      <div class="dv-screen">' +
      '        <div class="sc-top"><span class="sc-pt">ADULT</span><span class="sc-pads">3-LEAD</span><span class="sc-lead" data-o="lead">II</span><span class="sc-x" data-o="frozen" hidden>FROZEN</span><span class="sc-clock" data-o="clock">00:00</span><span class="sc-batt" aria-hidden="true"><i></i></span></div>' +
      '        <div class="sc-body">' +
      '          <div class="sc-waves">' +
      '            <div class="sc-wave ecg"><span class="sc-wl" data-o="wl">II  x1.0</span><canvas data-cv="ecg" aria-label="Live ECG"></canvas></div>' +
      '            <div class="sc-wave pl"><span class="sc-wl">SpO₂</span><canvas data-cv="pl"></canvas></div>' +
      '            <div class="sc-wave co"><span class="sc-wl">CO₂</span><canvas data-cv="co"></canvas></div>' +
      '          </div>' +
      '          <div class="sc-nums">' +
      '            <div class="sc-n hr"><small>HR</small><b data-o="hr">---</b><em>bpm</em></div>' +
      '            <div class="sc-n sp"><small>SpO₂ %</small><b data-o="sp">---</b></div>' +
      '            <div class="sc-n bp"><small>NIBP mmHg</small><b data-o="bp">---/---</b><em data-o="bpt">manual</em></div>' +
      '            <div class="sc-n co"><small>EtCO₂ mmHg</small><b data-o="co">--</b><em data-o="rr">RR --</em></div>' +
      '          </div>' +
      '        </div>' +
      '        <div class="sc-msg" data-o="msg" role="status" aria-live="polite">Monitoring</div>' +
      '      </div>' +
      '      <div class="dv-keys">' +
      '        <div class="kgrp"><span class="klab"><i>1</i>WATCH THE RHYTHM</span><div class="krow"><button class="key soft" data-k="lead">LEAD</button><button class="key soft led" data-k="freeze"><i class="led-dot"></i>FREEZE</button></div></div>' +
      '        <div class="kgrp"><span class="klab"><i>2</i>MEASURE</span><button class="key charge" data-k="print">PRINT STRIP</button><span class="khint">6-second paper strip with calipers</span></div>' +
      '        <div class="kgrp"><span class="klab"><i>3</i>ASSESS</span><button class="key soft" data-k="nibp">NIBP</button></div>' +
      '      </div>' +
      '    </div>' +
      '    <div class="dv-grill" aria-hidden="true"></div>' +
      '  </div>' +
      '</div>';
  }

  function Monitor(host, opts) {
    this.host = host; this.opts = opts || {};
    host.innerHTML = deviceHTML();
    this.o = {}; var self = this;
    Array.prototype.forEach.call(host.querySelectorAll('[data-o]'), function (x) { self.o[x.dataset.o] = x; });
    this.cv = {};
    this.leadI = 1; this.frozen = false; this.t = 0; this.raf = null;
    host.querySelector('.dv-keys').addEventListener('click', function (e) { var b = e.target.closest('[data-k]'); if (b) self.key(b.dataset.k); });
    host.querySelector('[data-k="sound"]').addEventListener('click', function () { self.setSound(!AU.on); });
    this.onResize = function () { self.setupCanvases(); };
    global.addEventListener('resize', this.onResize);
  }

  Monitor.prototype.setSound = function (on) {
    AU.on = on; try { localStorage.setItem('cshealthed-monitor-sound', on ? '1' : '0'); } catch (e) { /* ignore */ }
    if (AU.master) AU.master.gain.value = on ? 0.16 : 0;
    if (on) audio();
    var b = this.host.querySelector('[data-k="sound"]');
    b.setAttribute('aria-pressed', on ? 'true' : 'false'); b.classList.toggle('off', !on); b.querySelector('span').textContent = on ? 'SOUND ON' : 'SOUND OFF';
  };

  Monitor.prototype.setupCanvases = function () {
    var self = this;
    Array.prototype.forEach.call(this.host.querySelectorAll('[data-cv]'), function (c) {
      var r = c.getBoundingClientRect(), d = global.devicePixelRatio || 1;
      c.width = Math.max(10, Math.round(r.width * d)); c.height = Math.max(10, Math.round(r.height * d));
      var g = c.getContext('2d'); g.setTransform(d, 0, 0, d, 0, 0); g.lineJoin = 'round'; g.lineCap = 'round';
      self.cv[c.dataset.cv] = { c: c, g: g, w: r.width, h: r.height, px: 0, py: null };
    });
  };

  // Load a strip from the bank and start the monitor.
  Monitor.prototype.load = function (strip) {
    var sig = global.ECGEngine.generate(strip.r, strip.seed, BANK.seconds, BANK.gen);
    var rng = global.ECGEngine.mulberry32(strip.seed + 7);
    this.strip = strip; this.sig = sig;
    // loop between two beats so the join is seamless
    var q = sig.qrsTimes.filter(function (x) { return x > 0.8 && x < sig.duration - 0.8; });
    if (q.length >= 3 && q[q.length - 1] - q[0] > 6) { this.L0 = q[0] - 0.3; this.L1 = q[q.length - 1] - 0.3; }
    else { this.L0 = 0.3; this.L1 = sig.duration - 0.5; }
    var L0 = this.L0, L1 = this.L1;
    this.beatsLoop = sig.qrsTimes.filter(function (x) { return x >= L0 && x < L1; });
    this.spikesLoop = sig.spikes.filter(function (s) { return s.t >= L0 && s.t < L1; });
    this.perfusing = !PULSELESS[strip.r];
    this.beats = []; this.t = 0; this.frozen = false; this.lastBp = null;
    this.spo2 = this.perfusing ? 94 + Math.floor(rng() * 6) : null;
    this.etco2 = this.perfusing ? 33 + Math.floor(rng() * 8) : 5;
    this.rr = this.perfusing ? 12 + Math.floor(rng() * 7) : 10;
    var rate = sig.measuredRate, low = rate && (rate < 45 || rate > 150);
    this.bp = !this.perfusing ? '---/---' : low ? (78 + Math.floor(rng() * 18)) + '/' + (44 + Math.floor(rng() * 14)) : (104 + Math.floor(rng() * 38)) + '/' + (62 + Math.floor(rng() * 24));
    this.o.bp.textContent = '---/---'; this.o.bpt.textContent = 'manual';
    this.o.frozen.hidden = true;
    this.host.querySelector('[data-k="freeze"]').classList.remove('on');
    this.msg('Monitoring · Lead ' + LEADS[this.leadI]);
    this.setupCanvases();
    Object.keys(this.cv).forEach(function (k) { var o = this.cv[k]; o.g.clearRect(0, 0, o.w, o.h); }, this);
    this.updateNums();
    this.start();
  };

  Monitor.prototype.start = function () {
    var self = this;
    if (this.raf) cancelAnimationFrame(this.raf);
    var last = performance.now();
    function frame(ts) {
      var dt = Math.min(0.1, (ts - last) / 1000); last = ts;
      if (!self.frozen) {
        var t0 = self.t, t1 = t0 + dt; self.t = t1;
        self.events(t0, t1);
        self.drawEcg(t0, t1); self.drawPleth(t0, t1); self.drawCo2(t0, t1);
        self.o.clock.textContent = self.stamp();
        if (Math.floor(t1 * 2) !== Math.floor(t0 * 2)) self.updateNums();
      }
      self.raf = requestAnimationFrame(frame);
    }
    this.raf = requestAnimationFrame(frame);
  };

  // signal time for monitor time t (looping)
  Monitor.prototype.pos = function (t) { var L = this.L1 - this.L0; return this.L0 + (((t % L) + L) % L); };
  // things that happen between monitor times t0 and t1: beats and pacer spikes
  Monitor.prototype.events = function (t0, t1) {
    var L = this.L1 - this.L0, self = this;
    var a = t0 % L, b = t1 % L, base = t1 - b;
    function crossed(x) { var p = x - self.L0; return a <= b ? p > a && p <= b : p > a || p <= b; }
    function when(x) { var p = x - self.L0; return p <= b ? base + p : base - L + p; }
    this.firedSpikes = [];
    this.beatsLoop.forEach(function (x) {
      if (!crossed(x)) return;
      var at = when(x);
      self.beats.push(at); if (self.beats.length > 8) self.beats.shift();
      if (AU.on) tone(self.spo2 == null ? 700 : 520 + (self.spo2 - 80) * 20, 0, 0.075, 'sine', 0.9);
    });
    this.spikesLoop.forEach(function (s) { if (crossed(s.t)) self.firedSpikes.push({ at: when(s.t), s: s }); });
  };
  Monitor.prototype.hr = function () {
    var v = this.beats;
    if (v.length < 3 || this.t - v[v.length - 1] > 3) return null;
    var n = Math.min(4, v.length - 1), sum = 0;
    for (var i = v.length - n; i < v.length; i++) sum += v[i] - v[i - 1];
    return Math.round(60 / (sum / n));
  };
  Monitor.prototype.stamp = function () { var s = Math.floor(this.t); return String(Math.floor(s / 60)).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0'); };
  Monitor.prototype.updateNums = function () {
    var hr = this.hr();
    this.o.hr.textContent = hr == null ? '---' : hr;
    this.o.sp.textContent = this.spo2 == null ? '---' : this.spo2;
    this.o.co.textContent = this.etco2;
    this.o.rr.textContent = 'RR ' + this.rr;
  };
  Monitor.prototype.msg = function (txt, cls) { this.o.msg.textContent = txt; this.o.msg.className = 'sc-msg' + (cls ? ' ' + cls : ''); };

  Monitor.prototype.drawEcg = function (t0, t1) {
    var o = this.cv.ecg; if (!o) return;
    var g = o.g, pps = o.w / SWEEP, mid = o.h * 0.58, scale = o.h * 0.26, lead = LEADS[this.leadI];
    var n = Math.max(1, Math.round((t1 - t0) * 250));
    for (var i = 1; i <= n; i++) {
      var t = t0 + (t1 - t0) * i / n, xx = (t % SWEEP) * pps;
      if (xx < o.px) { o.px = 0; o.py = null; }
      g.clearRect(xx, 0, 14, o.h);
      var yv = Math.max(-1.9, Math.min(1.9, sampleAt(this.sig, lead, this.pos(t))));
      var yy = mid - yv * scale;
      if (o.py != null) { g.strokeStyle = '#3DF08E'; g.lineWidth = 1.6; g.beginPath(); g.moveTo(o.px, o.py); g.lineTo(xx, yy); g.stroke(); }
      o.px = xx; o.py = yy;
    }
    // pacemaker spikes, drawn as on the defib trainer
    for (var k = 0; k < this.firedSpikes.length; k++) {
      var sp = this.firedSpikes[k], ex = (sp.at % SWEEP) * pps, base = mid - sampleAt(this.sig, lead, sp.s.t) * scale;
      g.strokeStyle = '#FFFFFF'; g.lineWidth = 1.4; g.beginPath(); g.moveTo(ex, base); g.lineTo(ex, base - sp.s[lead] * scale * 1.2); g.stroke();
    }
  };
  Monitor.prototype.drawPleth = function (t0, t1) {
    var o = this.cv.pl; if (!o) return;
    var g = o.g, pps = o.w / SWEEP, n = Math.max(1, Math.round((t1 - t0) * 125)), vt = this.beats;
    for (var i = 1; i <= n; i++) {
      var t = t0 + (t1 - t0) * i / n, xx = (t % SWEEP) * pps; if (xx < o.px) { o.px = 0; o.py = null; }
      g.clearRect(xx, 0, 14, o.h);
      var y = 0;
      if (this.perfusing) {
        var d = 9;
        for (var j = vt.length - 1; j >= 0; j--) { if (vt[j] <= t) { d = t - vt[j]; break; } }
        if (d < 1.2) y = Math.exp(-Math.pow((d - 0.25) / 0.09, 2)) * 0.9 + Math.exp(-Math.pow((d - 0.45) / 0.08, 2)) * 0.25;
      }
      var yy = o.h * 0.85 - y * o.h * 0.65;
      if (o.py != null) { g.strokeStyle = '#4FD8F2'; g.lineWidth = 1.5; g.beginPath(); g.moveTo(o.px, o.py); g.lineTo(xx, yy); g.stroke(); }
      o.px = xx; o.py = yy;
    }
  };
  Monitor.prototype.drawCo2 = function (t0, t1) {
    var o = this.cv.co; if (!o) return;
    var g = o.g, pps = o.w / (SWEEP * 2), n = Math.max(1, Math.round((t1 - t0) * 125)), et = this.etco2, per = 60 / this.rr;
    for (var i = 1; i <= n; i++) {
      var t = t0 + (t1 - t0) * i / n, xx = (t % (SWEEP * 2)) * pps; if (xx < o.px) { o.px = 0; o.py = null; }
      g.clearRect(xx, 0, 14, o.h);
      var ph = (t % per) / per, y = ph < 0.12 ? 0 : (ph < 0.2 ? (ph - 0.12) / 0.08 : (ph < 0.62 ? 1 + (ph - 0.2) * 0.12 : (ph < 0.7 ? (1 - (ph - 0.62) / 0.08) : 0)));
      var yy = o.h * 0.9 - y * (et / 50) * o.h * 0.8;
      if (o.py != null) { g.strokeStyle = '#F5C842'; g.lineWidth = 1.5; g.beginPath(); g.moveTo(o.px, o.py); g.lineTo(xx, yy); g.stroke(); }
      o.px = xx; o.py = yy;
    }
  };

  Monitor.prototype.key = function (k) {
    if (!this.sig) return;
    audio(); // a key press unlocks sound in browsers that block it until the user acts
    if (k === 'lead') {
      this.leadI = (this.leadI + 1) % 3;
      var L = LEADS[this.leadI];
      this.o.lead.textContent = L; this.o.wl.textContent = L + '  x1.0';
      this.msg('Monitoring · Lead ' + L);
    } else if (k === 'freeze') {
      this.frozen = !this.frozen;
      this.o.frozen.hidden = !this.frozen;
      this.host.querySelector('[data-k="freeze"]').classList.toggle('on', this.frozen);
      this.msg(this.frozen ? 'Frozen · press FREEZE to resume' : 'Monitoring · Lead ' + LEADS[this.leadI], this.frozen ? 'info' : '');
    } else if (k === 'nibp') {
      this.o.bp.textContent = this.bp; this.o.bpt.textContent = this.stamp();
      this.msg(this.perfusing ? 'NIBP: ' + this.bp : 'NIBP: no reading', this.perfusing ? '' : 'warn');
    } else if (k === 'print') {
      // the 6 seconds just shown, in the current lead, as a paper strip
      var end = this.pos(this.t), start = end - 6;
      if (start < this.L0) start = Math.min(this.L1 - 6, this.L0 + 0.2);
      this.msg('Printing 6-second strip · Lead ' + LEADS[this.leadI], 'info');
      if (this.opts.onPrint) this.opts.onPrint({ sig: this.sig, start: start, lead: LEADS[this.leadI] });
    }
  };

  Monitor.prototype.destroy = function () {
    if (this.raf) cancelAnimationFrame(this.raf);
    this.raf = null;
    global.removeEventListener('resize', this.onResize);
  };

  global.ECGLiveMonitor = function (host, opts) { return new Monitor(host, opts); };
  global.ECGLiveMonitor.esc = esc;
})(window);
